-- Compares the engine against tests/fixtures/saturdays.tsv (generated by @hebcal/core).
local H = require('Module:HebrewDate')
local P = require('Module:Parsha')

local function cell(r)
    if r.holiday then return 'H' end
    local t = {}
    for i, v in ipairs(r.parshiot) do t[i] = tostring(v) end
    return table.concat(t, '+')
end

local rows, convFail, parFail = 0, 0, 0
for line in io.lines('tests/fixtures/saturdays.tsv') do
    if line:sub(1, 1) ~= '#' and line ~= '' then
        rows = rows + 1
        local gy, gm, gd, hy, hm, hd, il, dia = line:match('^(%d+)-(%d+)-(%d+)\t(%d+)\t(%d+)\t(%d+)\t(%S+)\t(%S+)$')
        gy, gm, gd, hy, hm, hd = tonumber(gy), tonumber(gm), tonumber(gd), tonumber(hy), tonumber(hm), tonumber(hd)
        local abs = H.gregorianToAbsolute(gy, gm, gd)
        local y, m, d = H.absoluteToHebrew(abs)
        local by, bm, bd = H.absoluteToGregorian(H.hebrewToAbsolute(hy, hm, hd))
        local okConv = y == hy and m == hm and d == hd and by == gy and bm == gm and bd == gd and abs % 7 == 6
        if not T.ok(okConv, line .. ' conversion got ' .. y .. '/' .. m .. '/' .. d) then convFail = convFail + 1 end
        local gotIl = cell(P.computeParsha(gy, gm, gd, true))
        local gotDia = cell(P.computeParsha(gy, gm, gd, false))
        if not T.ok(gotIl == il, line .. ' israel got ' .. gotIl) then parFail = parFail + 1 end
        if not T.ok(gotDia == dia, line .. ' diaspora got ' .. gotDia) then parFail = parFail + 1 end
    end
end
T.ok(rows > 6000, 'fixture has rows: ' .. rows)
print(string.format('fixture: %d rows, %d conversion mismatches, %d parsha mismatches', rows, convFail, parFail))
